import sys
import inspect
import taf.hw.rf_diagnostic_card.dispatcher.rmods.families  # noqa: F401


class RmodsConnectionsSetups:
    def __init__(self):
        self._rmods_families = "taf.hw.rf_diagnostic_card.dispatcher.rmods.families"
        self._setups = None

    @property
    def setups(self):
        if self._setups is None:
            self._setups = [
                obj
                for name, obj in inspect.getmembers(sys.modules[self._rmods_families])
                if inspect.isclass(obj) and obj.program
            ]
        return self._setups
